import { memo, useCallback } from 'react';
import { UserWalletResponse } from '~/entities/pin/api/dtos/schemas';
import i18n from '~/shared/i18n/i18n';
import { BottomSheet } from '~/shared/ui/bottom-sheets/bottom-sheet';

export type ManageMyWalletMoreMenuType =
  | 'manageWalletAlias'
  | 'autoOnOffRampSetting'
  | 'changeToBusinessAccount'
  | 'deleteWallet';

type ManageMyWalletMoreBottomSheetProps = {
  isSheetOpen: boolean;
  aliasNm: string;
  wallet: UserWalletResponse;
  hasBusinessAccount: boolean;
  onClose: () => void;
  onSelectMenu?: (menuType: ManageMyWalletMoreMenuType, aliasNm: string) => void;
};

const getMenuOptions = (hasBusinessAccount: boolean): { type: ManageMyWalletMoreMenuType; label: string }[] => [
  // {
  //   type: 'manageWalletAlias',
  //   label: i18n.t('manageMyWalletName'),
  // },
  {
    type: 'autoOnOffRampSetting',
    label: i18n.t('autoOnOffRampSetting'),
  },
  {
    type: 'changeToBusinessAccount',
    label: hasBusinessAccount ? i18n.t('manageBusinessAccount') : i18n.t('changeToBusinessAccount'),
  },
  {
    type: 'deleteWallet',
    label: i18n.t('deleteWallet'),
  },
];

export const ManageMyWalletMoreBottomSheet = memo(function ManageMyWalletMoreBottomSheet({
  isSheetOpen,
  aliasNm,
  wallet,
  hasBusinessAccount,
  onClose,
  onSelectMenu,
}: ManageMyWalletMoreBottomSheetProps) {
  const menuOptions = getMenuOptions(hasBusinessAccount);

  const handleSelectMenu = useCallback(
    (menuType: ManageMyWalletMoreMenuType) => {
      onSelectMenu?.(menuType, aliasNm);
    },
    [aliasNm, onSelectMenu],
  );

  return (
    <BottomSheet open={isSheetOpen} onClose={onClose} title="내 지갑 설정">
      <div className="bottom-sheet-content">
        <ul className="select-menu-list">
          {menuOptions.map((option) => (
            <li key={option.type} className="select-menu-item">
              <button type="button" className="btn-menu-link" onClick={() => handleSelectMenu(option.type)}>
                {option.label}
              </button>
            </li>
          ))}
        </ul>
      </div>
    </BottomSheet>
  );
});
