import clsx from 'clsx';
import { memo } from 'react';
import { useExchangeNavigation } from '~/entities/exchange/lib/use-exchange-navigation';
import { TokenItem } from '~/entities/pin/api/dtos/types';
import { ScannerType } from '~/entities/qr-scan/model/types';
import { useGetUserInfoQuery } from '~/entities/user/api/use-get-cstmr-query';
import { useUpdateDefaultWalletMutation } from '~/entities/wallet/api/use-update-default-wallet-mutation';
import { useTokenDetailType } from '~/entities/wallet/lib/use-token-detail-type';
import { TOKEN_DETAIL_CONFIG } from '~/entities/wallet/model/constants';
import { TrnscTypeCd } from '~/shared/api/dtos/enums';
import { usePaymentBottomSheet } from '~/shared/lib/hooks/use-payment-bottom-sheet';
import { PathType } from '~/shared/routes/paths';

type FunctionButtonsProps = {
  item: TokenItem;
  openQRScanner: (options: { scannerType: ScannerType }) => void;
  disabled?: boolean;
  aliasNmForUpdateDefault?: string;
};

type ClickProps = {
  trnscTypeCd: TrnscTypeCd;
  path: PathType;
};

export const FunctionButtons = memo(function FunctionButtons(props: FunctionButtonsProps) {
  const { data: userRes } = useGetUserInfoQuery();
  const isWalletBlocked = Boolean(props.disabled);
  const { openBottomSheet: openPaymentBottomSheet } = usePaymentBottomSheet();
  const { navigateToExchange } = useExchangeNavigation();
  const { tokenDetailType } = useTokenDetailType(props.item);
  const { mutateAsync: updateDefaultWallet } = useUpdateDefaultWalletMutation();
  const { item } = props;

  const handleClick =
    ({ trnscTypeCd, path }: ClickProps) =>
    async () => {
      if (props.aliasNmForUpdateDefault && userRes?.tbCstmrMastr?.aliasNm !== props.aliasNmForUpdateDefault) {
        await updateDefaultWallet(props.aliasNmForUpdateDefault);
      }

      if (trnscTypeCd === TrnscTypeCd.결제) {
        openPaymentBottomSheet(({ scannerType }) => {
          props.openQRScanner({ scannerType });
        });
        return;
      }

      navigateToExchange({
        path,
        item,
        trnscTypeCd,
      });
    };

  const buttons = TOKEN_DETAIL_CONFIG[tokenDetailType]?.functionButtons ?? [];
  const actionButtons = buttons.filter((b) => b.trnscTypeCd !== TrnscTypeCd.결제);
  const qrButton = buttons.find((b) => b.trnscTypeCd === TrnscTypeCd.결제);

  return (
    <section className="wallet-detail-action-container">
      <div className="wallet-detail-action-top">
        {actionButtons.map((button) => (
          <button
            key={button.buttonName}
            type="button"
            className={clsx(
              'btn-wallet-detail-action',
              { transfer: button.trnscTypeCd === TrnscTypeCd.송금 },
              { disabled: isWalletBlocked && !button?.essential },
            )}
            onClick={handleClick({
              trnscTypeCd: button.trnscTypeCd,
              path: button.path,
            })}
            disabled={isWalletBlocked && !button?.essential}
            aria-label={`${button.buttonName}하기`}
          >
            {button.buttonName}
          </button>
        ))}
      </div>
      {qrButton && (
        <div className="wallet-detail-action-bottom">
          <button
            type="button"
            className="btn-wallet-detail-qr"
            onClick={handleClick({
              trnscTypeCd: qrButton.trnscTypeCd,
              path: qrButton.path,
            })}
            disabled={isWalletBlocked && !qrButton?.essential}
          >
            <span className="wallet-detail-qr-title">QR 결제하기</span>
            <i aria-hidden="true" className="icon-wallet-detail-qr"></i>
          </button>
        </div>
      )}
    </section>
  );
});
