import { PaymentButtons } from '~/entities/home/ui/payment-buttons';
import { ScannerType } from '~/entities/qr-scan/model/types';
import i18n from '~/shared/i18n/i18n';
import { overlay } from '~/shared/lib/overlay';
import { BottomSheet } from '~/shared/ui/bottom-sheets/bottom-sheet';

type PaymentBottomSheetProps = {
  openQRScanner: (options: { scannerType: ScannerType }) => void;
};

export const usePaymentBottomSheet = () => {
  const openBottomSheet = (openQRScanner: (options: { scannerType: ScannerType }) => void) => {
    overlay.exclusiveOpen(({ isOpen, close, unmount }) => {
      return (
        <BottomSheet
          title={i18n.t('selectPaymentMethod')}
          centeredTitle
          afterLeave={unmount}
          open={isOpen}
          onClose={close}
        >
          <PaymentBottomSheet openQRScanner={openQRScanner} />
        </BottomSheet>
      );
    });
  };

  return { openBottomSheet };
};

const PaymentBottomSheet = ({ openQRScanner }: PaymentBottomSheetProps) => {
  return (
    <div className="env-bottom mb-[30px] ml-[30px] mr-[30px] mt-[20px]">
      <PaymentButtons openQRScanner={openQRScanner} />
    </div>
  );
};
